import json
from pathlib import Path
root = Path('products/services/open-software-tenders')
for path in sorted(root.rglob('*')):
    if not path.is_file():
        continue
    if path.name in {'source-105246-2026.json', 'source-105838-2026.json', 'source-106518-2026.json'} or any(term in str(path).lower() for term in ('amend', 'revision', 'comparison', 'trial')):
        item = {'path': str(path), 'bytes': path.stat().st_size}
        if path.suffix == '.json':
            try:
                data = json.loads(path.read_text())
            except (ValueError, UnicodeError):
                item['parse'] = 'invalid JSON'
            else:
                if isinstance(data, dict):
                    item['keys'] = sorted(data)[:30]
                    item['releases'] = [{key: release.get(key) for key in ('id', 'ocid', 'date', 'tag')} for release in data.get('releases', [])[:12] if isinstance(release, dict)] if isinstance(data.get('releases'), list) else []
                    item['record_count'] = len(data['records']) if isinstance(data.get('records'), list) else None
        print(json.dumps(item, ensure_ascii=True))
